fn frame(t: i32) {
    host::display::clear(0x000005);
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let ax: i32 = (w * 2) / 5;
    let ay: i32 = (h * 2) / 5;
    let mut px: i32 = 0;
    let mut py: i32 = 0;
    let mut a: i32 = 0;
    while a <= 256 {
        let x: i32 = cx + (ax * host::math::cos(a * 3 + t)) / 256;
        let y: i32 = cy + (ay * host::math::sin(a * 2)) / 256;
        if a > 0 {
            host::display::draw_line(px, py, x, y, 0xffaa33);
        }
        px = x;
        py = y;
        a = a + 2;
    }
    host::display::present();
}
